        for r in resources:
            score = manhattan(pos, r)
            if score < best_score:
                best_score = score
                best = r
        return step_toward(pos, best)

    # General fallback: chase if close, otherwise move toward map center if known.
    if width and height:
        center = (width // 2, height // 2)
        if manhattan(pos, opp) <= 2:
            return step_toward(pos, opp)
        return step_toward(pos, center)

    return step_toward(pos, opp)

